package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real adapter/templates with executor/manager doubles; no portal link, revocation or engine evidence. */
public class SqlServerPortalPatientsStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",DOCUMENT="cc000000-0000-4000-8000-000000000001",PATIENT="dd000000-0000-4000-8000-000000000001",OTHER="ee000000-0000-4000-8000-000000000001",DATE="2026-11-05T00:00:00.123456Z";
 public static Map<String,Object> row(){var r=new LinkedHashMap<String,Object>();r.put("id",PATIENT);r.put("name","Synthetic \u4e2d\ud83e\uddb7");r.put("domain","HUMAN");r.put("birthDate",null);r.put("species",null);r.put("relationship","Synthetic relationship");r.put("scopes",new ArrayList<>(List.of("DOCUMENTS","APPOINTMENTS","BILLING")));return r;}
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final SqlServerPortalPatientsStore store=new SqlServerPortalPatientsStore(executor,manager);public final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/portal/patients");public Actor actor;public List<Map<String,Object>> rows=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();public final List<List<Object>> args=new ArrayList<>();public final List<SqlServerContext> contexts=new ArrayList<>();
  public Fixture(){actor("PAC");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.PORTAL_PATIENTS,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());contexts.add(c);args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));manager.events.add("sp:PORTAL_PATIENTS");return results.isEmpty()?new SqlServerExecutor.Result(List.of(rows),List.of()):results.removeFirst();});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("PORTAL")));request.setAttribute("health.requestId",OTHER);}
 }
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable r){var e=assertThrows(ApiException.class,r::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void oneSpOneArgumentRequestContextAndExactImmutableNineFieldProjection(){var row=row();row.put("passwordHash","private-canary");row.put("tenantId",OTHER);row.put("active",false);f.rows.add(row);TraceContext.REQUEST.set(new MockHttpServletRequest());var output=f.store.patients(f.request);assertEquals(7,output.getFirst().size());assertEquals(Set.of("id","name","domain","birthDate","species","relationship","scopes"),output.getFirst().keySet());assertFalse(output.toString().contains("private-canary"));assertFalse(output.getFirst().containsKey("active"));assertFalse(output.getFirst().containsKey("tenantId"));assertEquals(List.of(),f.args.getFirst());assertEquals(List.of("PAC"),f.contexts.getFirst().roles());assertEquals(List.of("begin:0","sp:PORTAL_PATIENTS","commit"),f.manager.events);assertThrows(UnsupportedOperationException.class,output::clear);assertThrows(UnsupportedOperationException.class,output.getFirst()::clear);}
 @Test void emptyAndUnboundedRowsPreserveSpNameIdOrderAndUnicode(){assertTrue(f.store.patients(f.request).isEmpty());for(int i=0;i<1001;i++){var row=row();row.put("id",UUID.nameUUIDFromBytes(("synthetic-"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());row.put("name",String.format(java.util.Locale.ROOT,"Synthetic%04d",i));f.rows.add(row);}var output=f.store.patients(f.request);assertEquals(1001,output.size());assertEquals(f.rows.getFirst(),output.getFirst());assertEquals(f.rows.getLast(),output.getLast());}
 @Test void nullableDateSpeciesEmptyScopesAndFullScopesCopiedImmutable(){var row=row();row.put("scopes",List.of());f.rows.add(row);var out=f.store.patients(f.request).getFirst();assertTrue(out.containsKey("birthDate"));assertNull(out.get("birthDate"));assertNull(out.get("species"));assertEquals(List.of(),out.get("scopes"));f.rows.clear();row=row();var original=(List<String>)row.get("scopes");f.rows.add(row);out=f.store.patients(f.request).getFirst();var scopes=(List<?>)out.get("scopes");original.clear();assertEquals(List.of("DOCUMENTS","APPOINTMENTS","BILLING"),scopes);assertThrows(UnsupportedOperationException.class,scopes::clear);}
 @Test void rolesAndModuleRevalidatedButNoStatusOrCoreGateAdded(){for(String role:List.of("PAC","RES")){f.actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("PORTAL")));assertTrue(f.store.patients(f.request).isEmpty());}for(String role:List.of("ADM","REC","PRO","ASI","AUD","SAD","SOP")){f.actor(role);assertEquals(403,assertThrows(ApiException.class,()->f.store.patients(f.request)).status);}f.actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE")));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.patients(f.request)).code);assertEquals(2,f.args.size());}
 @Test void nullRequestForgedContextUuidAndTokenFailBeforeExecutor(){safe(()->f.store.patients(null));f.request.setAttribute("health.tenant","bad");safe(()->f.store.patients(f.request));f.actor("PAC");f.request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->f.store.patients(f.request)).status);f.actor("PAC");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"a".repeat(64)));safe(()->f.store.patients(f.request));f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"bad"));safe(()->f.store.patients(f.request));f.actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("PORTAL")));assertEquals(403,assertThrows(ApiException.class,()->f.store.patients(f.request)).status);verifyNoInteractions(f.executor);}
 @Test void domainDateSpeciesAndFieldBoundsMatchDeclaredSchema(){for(String domain:List.of("HUMAN","ANIMAL")){var row=row();row.put("domain",domain);row.put("birthDate","9999-12-31");row.put("species",null);f.rows.clear();f.rows.add(row);assertEquals(domain,f.store.patients(f.request).getFirst().get("domain"));}var row=row();row.put("name","\u4e2d".repeat(160));row.put("relationship","\u4e2d".repeat(80));row.put("species","\u4e2d".repeat(80));row.put("birthDate","0001-01-01");f.rows.clear();f.rows.add(row);assertEquals(row,f.store.patients(f.request).getFirst());}
 @Test void absentMultipleResultsetsAndWrongCardinalityAreDatabaseErrors(){for(var result:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()))){f.results.add(result);safe(()->f.store.patients(f.request));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void allFieldsRequiredAndInvalidValuesScopesAndDatesAreRejected(){for(String key:row().keySet()){var bad=row();bad.remove(key);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.patients(f.request));if(Set.of("birthDate","species").contains(key))continue;bad=row();bad.put(key,null);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.patients(f.request));}for(var entry:List.of(Map.entry("id","bad"),Map.entry("name",1),Map.entry("name"," "),Map.entry("name","x".repeat(161)),Map.entry("domain","human"),Map.entry("domain","bad"),Map.entry("birthDate","2026-02-30"),Map.entry("birthDate","2026-1-01"),Map.entry("birthDate","0000-01-01"),Map.entry("birthDate","+10000-01-01"),Map.entry("birthDate",java.time.LocalDate.of(2026,1,1)),Map.entry("species",1),Map.entry("species","x".repeat(81)),Map.entry("relationship",""),Map.entry("relationship","x".repeat(81)),Map.entry("scopes",Set.of("DOCUMENTS")),Map.entry("scopes","[]"),Map.entry("scopes",List.of("DOCUMENTS","DOCUMENTS")),Map.entry("scopes",List.of("documents")),Map.entry("scopes",List.of(1)),Map.entry("scopes",Arrays.asList((String)null)))){var bad=row();bad.put(entry.getKey(),entry.getValue());f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.patients(f.request));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void moduleLinkAndPermissionSpErrorsAreMappedWithoutRetryOrFakeEmpty(){for(int vendor:List.of(51001,51002,51003)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->f.store.patients(f.request));assertEquals(vendor==51001?403:vendor==51002?404:409,error.status);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));}verify(f.executor,times(3)).execute(eq(SqlServerProcedure.PORTAL_PATIENTS),any());}
 @Test void requiredJoinMappingRollbackAndCommitFailureNeverFallBack(){assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.patients(f.request);assertFalse(f.manager.events.contains("commit"));throw new RuntimeException("cancel");}));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;safe(()->f.store.patients(f.request));assertEquals(2,f.args.size());assertEquals("SqlServerPortalPatientsStore[redacted]",f.store.toString());}
}
